"""Build the self-contained current presentation from editable local sources."""
from pathlib import Path
import html
import json
import re

ROOT = Path(__file__).resolve().parents[1]
REF = ROOT / 'deck/reference'

def recovered(n, final_number):
    svg = (REF / f'{n:02}.svg').read_text()
    spans = json.loads((REF / f'{n:02}.json').read_text())
    out = []
    for s in spans:
        text = s['text']
        if re.fullmatch(r'\d\d / 16', text): text = f'{final_number:02} / 20'
        if n == 2 and text == 'Cómo participar': text = 'Cómo participamos'
        if n == 14: text = text.replace('Edhú Nuñes', 'Edhú Núñez')
        family = 'Space Grotesk' if 'SpaceGrotesk' in s['font'] else 'Geist Mono' if 'GeistMono' in s['font'] else 'Inter Tight'
        weight = 600 if 'SemiBold' in s['font'] else 500 if 'Medium' in s['font'] else 400
        x, y = s['origin']; width = s['bbox'][2] - s['bbox'][0]
        # The agenda replacement is longer; allow its natural width.
        fit = '' if text == 'Cómo participamos' else f'data-width="{width:.3f}"'
        out.append(f'<span class="pdf-text" {fit} style="left:{x:.3f}px;top:{y:.3f}px;font-family:\'{family}\';font-weight:{weight};font-size:{s["size"]:.3f}px;color:#{s["color"]:06x}">{html.escape(text)}</span>')
    return '<section class="canvas recovered">' + svg + ''.join(out) + '</section>'

css = r'''*{box-sizing:border-box}html,body{margin:0;background:#000;font-family:"Inter Tight",sans-serif}body{color:#191a18}.slide{width:100vw;height:100vh;height:100dvh;display:flex;align-items:center;justify-content:center;overflow:hidden;page-break-after:always}.frame{width:calc(1152px * var(--scale));height:calc(648px * var(--scale));position:relative;flex:none}.canvas{width:1152px;height:648px;position:absolute;top:0;left:0;transform:scale(var(--scale));transform-origin:top left;overflow:hidden}.recovered svg{position:absolute;inset:0;width:100%;height:100%}.pdf-text{position:absolute;white-space:pre;line-height:1;transform:translateY(-.8em) scaleX(var(--fit,1));transform-origin:left top}.new-slide{padding:0 58px;background:#f5f3ec;color:#191a18}.new-slide.dark{background:#000;color:#fff}.new-slide header{position:absolute;top:32px;left:58px;right:58px;display:flex;justify-content:space-between;align-items:center}.new-slide header b{font:600 17px "Space Grotesk"}.new-slide header span,.new-slide footer,.number,.tag,.example strong,.support strong{font-family:"Geist Mono",monospace}.new-slide header span{font-size:13px;color:#62645b}.dark header span{color:#c7c7cc}.new-slide main{position:absolute;top:96px;left:58px;right:58px;bottom:54px}.tag{font-size:12px;display:inline-block;border-left:3px solid;border-right:3px solid;padding:2px 9px;margin-bottom:16px}.new-slide h1{font:600 42px/1.07 "Space Grotesk";letter-spacing:-.035em;margin:0;max-width:1020px}.intro{font-size:18px;line-height:1.35;max-width:1000px;margin:16px 0 0}.columns{display:grid;gap:42px;margin-top:30px}.three{grid-template-columns:repeat(3,1fr)}.professional{grid-template-columns:2.05fr 1fr}.columns article{border-top:1px solid #cecec4;padding-top:14px;min-width:0}.dark .columns article{border-color:#45454a}.number{font-size:13px;color:#62645b}.dark .number{color:#c7c7cc}.new-slide h2{font:600 24px/1.12 "Space Grotesk";letter-spacing:-.025em;margin:9px 0}.new-slide article p,.support p,.agreement p,.project p{font-size:17px;line-height:1.32;margin:8px 0}.compact h2{font-size:21px}.compact article p{font-size:15.5px;line-height:1.3}.example{margin-top:15px;border-left:3px solid #8e8eff;padding-left:11px}.example strong,.support strong{font-size:10px;font-weight:500}.example p{margin:5px 0!important}.examples-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.examples-grid .example p{font-size:14px}.note{font-size:13px;line-height:1.3;position:absolute;bottom:0;margin:0;color:#62645b}.dark .note{color:#c7c7cc}.flowline{display:flex;gap:9px;align-items:center;margin-top:20px;border-top:1px solid #cecec4;padding-top:12px;font:500 12px/1.25 "Geist Mono"}.flowline b{color:#8e8eff;font-size:20px}.project-layout{display:grid;grid-template-columns:1fr 1.6fr;gap:38px;margin-top:27px}.project{border-left:6px solid #8e8eff;padding:12px 20px;background:#eceae2}.project p{font-family:"Space Grotesk";font-size:19px}.support h2,.agreement h2{margin:0 0 12px;font-size:20px}.support-items{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.support-items>div{border-top:1px solid #cecec4;padding-top:12px}.support-items p{font-size:15px}.agreement{display:grid;grid-template-columns:1fr 2.5fr;gap:30px;border-top:1px solid #cecec4;margin-top:28px;padding-top:15px}.agreement p{font-size:15px;margin:0}.new-slide footer{position:absolute;bottom:30px;left:58px;right:58px;display:flex;align-items:center;justify-content:space-between;font-size:11px;color:#62645b}.new-slide footer i{width:86px;height:2px;background:#8e8eff}.controls{position:fixed;right:12px;bottom:12px;display:flex;gap:4px;opacity:.1;transition:opacity .2s;z-index:5}.controls:hover,.controls:focus-within{opacity:1}.controls button{background:#242426;color:white;border:1px solid #777;padding:7px 11px;cursor:pointer}@media print{@page{size:1152px 648px;margin:0}.slide{width:1152px;height:648px;display:block}.frame{width:1152px;height:648px}.canvas{transform:none}.controls{display:none}body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}'''
css += '.controls{opacity:0}#slide-18 h1,#slide-19 h1{font-size:35px}#slide-18 .columns{margin-top:20px}#slide-18 .compact article p{font-size:14.5px}#slide-18 .example{margin-top:10px}#slide-18 .flowline{margin-top:14px}#slide-19 .agreement{margin-top:18px}'
script = r'''const slides=[...document.querySelectorAll('.slide')];let current=0;function scale(){document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1152,innerHeight/648));}function go(n){current=Math.max(0,Math.min(slides.length-1,n));slides[current].scrollIntoView({behavior:'instant'});history.replaceState(null,'','#slide-'+String(current+1).padStart(2,'0'));}window.deck={goTo:n=>go(n-1),get current(){return current+1},get count(){return slides.length}};addEventListener('resize',scale);scale();document.fonts.ready.then(()=>{document.querySelectorAll('[data-width]').forEach(e=>{const w=e.getBoundingClientRect().width/Math.min(innerWidth/1152,innerHeight/648);if(w)e.style.setProperty('--fit',e.dataset.width/w)});document.documentElement.dataset.fonts='ready'});document.addEventListener('keydown',e=>{if(['ArrowRight','ArrowDown','PageDown',' '].includes(e.key)){e.preventDefault();go(current+1)}else if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();go(current-1)}else if(e.key==='Home')go(0);else if(e.key==='End')go(slides.length-1)});document.querySelector('#prev').onclick=()=>go(current-1);document.querySelector('#next').onclick=()=>go(current+1);document.querySelector('#full').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen?.();const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)current=slides.indexOf(e.target)}),{threshold:.6});slides.forEach(s=>observer.observe(s));let x;document.addEventListener('touchstart',e=>x=e.changedTouches[0].clientX,{passive:true});document.addEventListener('touchend',e=>{let d=e.changedTouches[0].clientX-x;if(Math.abs(d)>60)go(current+(d<0?1:-1))},{passive:true});'''
new = (ROOT/'deck/participacion.html').read_text()
parts = re.findall(r'<section class="new-slide.*?</section>', new, flags=re.S)
assert len(parts) == 5
sections = [recovered(n,n) for n in range(1,15)] + [s.replace('class="new-slide ', 'class="canvas new-slide ', 1) for s in parts] + [recovered(16,20)]
wrapped = ''.join(f'<div class="slide" id="slide-{i:02}"><div class="frame">{s}</div></div>' for i,s in enumerate(sections,1))
fontcss = (ROOT/'deck/fonts.css').read_text()
doc = f'<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI PlayGrounds</title><style>{fontcss}\n{css}</style></head><body><div>{wrapped}</div><nav class="controls" aria-label="Navegación"><button id="prev" aria-label="Anterior">←</button><button id="next" aria-label="Siguiente">→</button><button id="full" aria-label="Pantalla completa">⛶</button></nav><script>{script}</script></body></html>'
(ROOT/'output').mkdir(exist_ok=True)
(ROOT/'output/deck.html').write_text(doc)
print('20 diapositivas generadas')
